def range_compress(values):
    if not values:
        return []
    distinct = sorted(set(values))
    result = []
    run_start = distinct[0]
    prev = distinct[0]
    for v in distinct[1:]:
        if v == prev + 1:
            prev = v
        else:
            result.append([run_start, prev])
            run_start = v
            prev = v
    result.append([run_start, prev])
    return result
